<script setup lang="ts">import{computed,inject,ref}from'vue';import ZtIcon from'../icon/ZtIcon.vue';import{collapseKey}from'./context';import type{ZtCollapseItemProps}from'./types';defineOptions({name:'ZtCollapseItem'});const props=withDefaults(defineProps<ZtCollapseItemProps>(),{disabled:false,lazy:false});const context=inject(collapseKey)!,seen=ref(false),open=computed(()=>context.active.value.includes(props.name));const id=`zt-collapse-${Math.random().toString(36).slice(2)}`;const rendered=computed(()=>{if(open.value)seen.value=true;return!props.lazy||seen.value});function toggle(){if(!props.disabled)context.toggle(props.name)}</script>
<template><section class="zt-collapse-item" :class="{'is-open':open,'is-disabled':disabled}"><button type="button" class="zt-collapse-item__header" :aria-expanded="open" :aria-controls="id" :disabled="disabled" @click="toggle"><span><slot name="title">{{title}}</slot></span><ZtIcon name="arrow-down" class="zt-collapse-item__arrow" /></button><div v-if="rendered" v-show="open" :id="id" class="zt-collapse-item__panel" role="region"><div class="zt-collapse-item__content"><slot /></div></div></section></template>
